// Eval fourth1 (snd-wand-spells): `description: A magic wand with three spells: fireball, frost` is not valid YAML (a ": " inside a
// plain scalar). Every such value on a `key: value` line is double-quoted; the result must parse (parse = YAML.parse) or nothing is
// changed. Block scalars (| >) and already quoted / flow values are left alone. Returns the fixed text or null.
function fixYamlScalars(text, parse) {
  const lines = String(text).split("\n");
  let blockIndent = -1;
  let changed = 0;
  const out = lines.map((line) => {
    const ind = line.length - line.trimStart().length;
    if (blockIndent >= 0) { if (!line.trim() || ind > blockIndent) return line; blockIndent = -1; }
    const m = /^(\s*(?:-\s+)?[A-Za-z_][\w.-]*:[ \t]+)(.*?)\s*$/.exec(line);
    if (!m) return line;
    const v = m[2];
    if (/^[|>]/.test(v)) { blockIndent = ind; return line; }
    if (!v || /^["'\[{&*!%@`#|>]/.test(v)) return line;
    if (!/:(\s|$)/.test(v)) return line;
    changed++;
    return `${m[1]}"${v.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
  });
  if (!changed) return null;
  const fixed = out.join("\n");
  try { parse(fixed); } catch { return null; }
  return fixed;
}

