// Pure Test Flight verdicts. Rules (never relaxed):
// - a check counts as passed only if its status is "pass" AND it carries evidence (a pass with no evidence = not run);
// - required stages come from the spec we sent (requiredStages), not from the runner's own flags;
// - any required stage failed -> "failed"; any required stage missing / not_run -> "incomplete"; neither is success;
// - a busy or errored runner is never success, whatever its checks say.
import type { CheckId, CheckResult, MatrixSummary, Overall, TestFlightReport, TestFlightSpec, TestFlightSummary } from "./types";
import { CHECK_IDS } from "./types";
import { requiredStages } from "./spec";

const STATUSES = new Set(["pass", "fail", "not_run"]);

/** Normalise one check: unknown status or a pass without evidence becomes not_run. */
function effective(c: CheckResult | undefined): "pass" | "fail" | "not_run" {
  if (!c || !STATUSES.has(c.status)) return "not_run";
  if (c.status === "pass" && !(Array.isArray(c.evidence) && c.evidence.some((e) => String(e).trim()))) return "not_run";
  return c.status;
}

export function summarize(spec: TestFlightSpec, report: TestFlightReport): TestFlightSummary {
  const req = requiredStages(spec);
  const byId = new Map<CheckId, CheckResult>();
  for (const c of report.checks ?? []) if ((CHECK_IDS as readonly string[]).includes(c.id) && !byId.has(c.id)) byId.set(c.id, c);
  const passed: CheckId[] = [], failed: CheckId[] = [], skippedRequired: CheckId[] = [], notRunOptional: CheckId[] = [];
  const reasons: string[] = [];
  for (const id of CHECK_IDS) {
    const c = byId.get(id);
    const st = effective(c);
    if (st === "pass") passed.push(id);
    else if (st === "fail") { failed.push(id); if (req.has(id)) reasons.push(`${id} failed${c?.evidence?.[0] ? `: ${c.evidence[0]}` : ""}`); }
    else if (req.has(id)) {
      skippedRequired.push(id);
      reasons.push(!c ? `${id} missing from the report` : c.status === "pass" ? `${id} claimed pass without evidence` : `${id} did not run`);
    } else notRunOptional.push(id);
  }
  if (report.version && spec.version && report.version !== spec.version) reasons.push(`report is for ${report.version}, spec asked for ${spec.version}`);
  let overall: Overall;
  if (report.status === "busy") { overall = "busy"; reasons.unshift("another Test Flight was running; nothing ran"); }
  else if (report.status !== "completed") { overall = "error"; reasons.unshift(`runner did not complete: ${report.notes?.slice(-1)[0] ?? "no detail"}`); }
  else if (report.version !== spec.version) overall = "error";
  else if (failed.some((id) => req.has(id))) overall = "failed";
  else if (skippedRequired.length) overall = "incomplete";
  else overall = "passed";
  return {
    version: spec.version, overall, success: overall === "passed", passed, failed, skippedRequired, notRunOptional, reasons,
    bootMs: report.bootMs ?? null, peakRssKb: report.peakRssKb ?? null, runId: report.runId ?? null,
  };
}

/** One verdict over several versions: success only if every version passed. Worst status wins. */
export function mergeSummaries(list: TestFlightSummary[]): MatrixSummary {
  const rank: Overall[] = ["error", "failed", "busy", "incomplete", "passed"];
  const overall = list.length ? rank.find((r) => list.some((s) => s.overall === r))! : "incomplete";
  return { overall, success: overall === "passed", versions: list };
}

/** Short human line per version, e.g. for a build log or a badge tooltip. Never says "passed" unless it did. */
export function describe(s: TestFlightSummary): string {
  const t = s.bootMs != null ? `, boot ${(s.bootMs / 1000).toFixed(1)}s` : "";
  const r = s.peakRssKb != null ? `, peak RSS ${Math.round(s.peakRssKb / 1024)} MB` : "";
  if (s.success) return `Test Flight passed on Paper ${s.version} (${s.passed.length} checks${t}${r})`;
  return `Test Flight ${s.overall} on Paper ${s.version}: ${s.reasons.slice(0, 3).join("; ") || "no detail"}`;
}
