export async function setCyrusPageVisibility(slug: string, visibility: "PUBLIC" | "PRIVATE"): Promise<{ ok?: true; error?: string }> {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const page = await pageFor(slug, user);
  if (!page) return NF;
  if (page.userId !== user.id) return { error: "Only the mod's creator can publish it." };
  if (visibility !== "PUBLIC" && visibility !== "PRIVATE") return { error: "Bad visibility." };
  if (visibility === "PUBLIC" && (await cyrusSuspension(user.id, "community"))) return { error: SUSPENDED };
  if (visibility === "PUBLIC" && process.env.CYRUS_TESTFLIGHT_BLOCK_ON_FAIL === "1") {
    // Cyrus R5 optional gate: the current version's Test Flight must not have FAILED ("not run" never blocks)
    const chain = await loadChain(page.rootBuildId);
    const head = currentVersion(chain);
    const fb = flightBlocks((head?.cyrus as { testFlight?: unknown } | null | undefined)?.testFlight);
    if (fb.blocked) return { error: fb.reason };
  }
  await cyrusDb.cyrusModPage.update({ where: { id: page.id }, data: { visibility, ...(visibility === "PUBLIC" && !page.publishedAt ? { publishedAt: new Date() } : {}) } });
  await db.auditLog.create({ data: { userId: user.id, action: "cyrusmods.visibility", detail: `${page.slug} ${visibility}` } }).catch(() => {});
  revalidate(page.slug);
  revalidatePath("/dashboard/nxlabs/cyrus");
  return { ok: true };
}

