export function readStoredFlight(raw: unknown): StoredFlight | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const r = raw as StoredFlight;
  return r.schema === 1 && typeof r.state === "string" && Array.isArray(r.checks) ? r : null;
}

/** Is this build due a flight now? (pure scheduling) */
export function dueForFlight(stored: StoredFlight | null, now: Date): boolean {
  if (!stored) return true;
  if (stored.state === "queued") return !stored.nextAt || new Date(stored.nextAt).getTime() <= now.getTime();
  if (stored.state === "running") return new Date(stored.at).getTime() < now.getTime() - 30 * 60_000; // a worker died mid-flight
  return false;
}

/** Optional gate on publish / install: only a FAILED flight blocks, and only with the flag on. "Not run" never blocks. */
export function flightBlocks(stored: unknown, env: Record<string, string | undefined> = process.env): { blocked: false } | { blocked: true; reason: string } {
  const f = readStoredFlight(stored);
  // perf safety: a FAILED stress test blocks by default, independent of CYRUS_TESTFLIGHT_BLOCK_ON_FAIL (CYRUS_PERF_BLOCK_ON_FAIL=0 = off)
  if (f?.state === "done" && f.stress) { const sb = stressBlocks(f.stress, f.version, env); if (sb.blocked) return sb; }
  if (env[BLOCK_FLAG] !== "1") return { blocked: false };
  if (f?.state === "done" && f.verdict === "failed") {
    const bad = f.checks.filter((c) => c.status === "fail").map((c) => c.id.replace(/_/g, " "));
    return { blocked: true, reason: `This version failed its Test Flight on Paper ${f.version} (${bad.join(", ") || "boot"}). Fix it with a change request before installing or publishing it.` };
  }
  return { blocked: false };
}

/** Customer-facing lines for the NxLabs mod page (honest: not run is never shown as passed). */
export function flightLines(stored: unknown): string[] {
  const f = readStoredFlight(stored);
  if (!f) return [];
  const name: Record<GateCheckId, string> = { compile: "Compiles", scan: "Safety scan", boot: "Server boots", plugins_enabled: "Plugin enables", commands_registered: "Commands register", datapack_loaded: "Data pack loads" };
  const word = { pass: "passed", fail: "FAILED", not_run: "not run" } as const;
  const head = f.label ? `Boot-tested on Paper ${f.version} (a real server started with this version; this does not test gameplay).`
    : f.verdict === "failed" ? `Failed its boot test on Paper ${f.version}.`
    : f.state === "queued" || f.state === "running" ? `Boot test on Paper ${f.version} is queued.`
    : `Not boot-tested${f.reason ? `: ${f.reason.replace(/^not run: /, "")}` : ""}.`;
  return [head, ...f.checks.map((c) => `${name[c.id]}: ${word[c.status]}`), ...(f.stress ? [f.stress.label] : []), ...(f.worldgen ? [f.worldgen.label] : [])];
}
