        {!TERMINAL.has(status) ? <span className="cx-faint" style={{ fontSize: 12.5 }} suppressHydrationWarning>{elapsed} so far, usually a few minutes</span> : null}
      </div>
      <p className="cx-muted" style={{ margin: 0, fontSize: 13 }}>{failed ? error || "Nothing more is charged for a failed build, and tokens held for it are returned. You can change the prompt and try again." : status === "queued" ? queueLine(queue).detail : PLAIN[status] ?? "Almost there."}</p>
      <ol className="cx-steps" aria-label="Build steps" style={{ listStyle: "none", padding: 0, margin: 0 }}>
        {CYRUS_STAGES.filter((s) => s.key !== "repairing").map((s) => {
