import { cyrusDb } from "../cyrus/db";
import { db } from "../db";
import { getSetting } from "../settings";

export const FEATURED_KEY = "cyrus_featured_pages";
export const FEATURED_MAX = 12;

export function parseFeatured(raw: string | null | undefined): string[] {
  if (!raw) return [];
  try {
    const v = JSON.parse(raw) as unknown;
    if (!Array.isArray(v)) return [];
    const out: string[] = [];
    for (const x of v) if (typeof x === "string" && /^[A-Za-z0-9_-]{1,64}$/.test(x) && !out.includes(x)) out.push(x);
    return out.slice(0, FEATURED_MAX);
  } catch { return []; }
}

export function setFeatured(list: string[], id: string, on: boolean): { ok: true; list: string[] } | { ok: false; error: string } {
  const has = list.includes(id);
  if (!on) return { ok: true, list: list.filter((x) => x !== id) };
  if (has) return { ok: true, list };
  if (list.length >= FEATURED_MAX) return { ok: false, error: `At most ${FEATURED_MAX} mods can be featured. Unfeature one first.` };
  return { ok: true, list: [...list, id] };
}

