  creator: string;
  game: string;
  gameVersion: string | null;
  version: string | null;
  /** average of other accounts' ratings (1-5), null until someone rated it */
  rating: number | null;
  ratings: number;
  stars: number;
  iconUrl: string | null;
};

export type FeaturablePage = { visibility: string; hiddenAt: Date | null };
/** Public AND not taken down: the only pages that may be featured or shown. */
export const isFeaturable = (p: FeaturablePage) => p.visibility === "PUBLIC" && !p.hiddenAt;

export async function readFeaturedIds(): Promise<string[]> {
  return parseFeatured(await getSetting(FEATURED_KEY, "").catch(() => ""));
}

/** The public cards, in the owner's order. Empty = hide the section. Never throws. */
export async function loadFeaturedCards(): Promise<FeaturedCard[]> {
  try {
    const ids = await readFeaturedIds();
    if (!ids.length) return [];
    const pages = await cyrusDb.cyrusModPage.findMany({ where: { id: { in: ids }, visibility: "PUBLIC", hiddenAt: null } });
    if (!pages.length) return [];
    const [{ statsFor, listingsFor, toListingView }, { displayUser }, { readModDoc }] = await Promise.all([import("./social"), import("./pages"), import("./doc")]);
    const [stats, { listings, media }, users] = await Promise.all([
      statsFor(pages).catch(() => new Map()),
      listingsFor(pages.map((p) => p.id)).catch(() => ({ listings: new Map(), media: new Map() })),
      db.user.findMany({ where: { id: { in: [...new Set(pages.map((p) => p.userId))] } }, select: { id: true, name: true } }).catch(() => []),
