// Customer-app view models (r39). PURE: takes rows the pages already loaded, returns what the screens show.
// Nothing here invents a number: counts come from the rows, a missing value stays missing.
import type { ModBuildView } from "../builder/types";
import { groupProjects, type CyrusProject } from "../projects";
import { readCyrusMeta } from "../meta";

export type FlightBadge = { tone: "ok" | "bad" | "warn" | "wait" | "none"; label: string; detail: string | null };

/** The Test Flight record a build carries (written by the gate worker), as a badge. Never "passed" without a done
 *  flight with a passed verdict. */
export function flightBadge(b: Pick<ModBuildView, "status" | "cyrus">): FlightBadge {
  if (b.status !== "succeeded") return { tone: "none", label: "No Test Flight", detail: "Only finished builds fly." };
  const f = readCyrusMeta(b.cyrus).testFlight as Record<string, unknown> | undefined;
  if (!f) return { tone: "none", label: "Not flown", detail: "No Test Flight on record for this build." };
  const state = String(f.state ?? ""), verdict = String(f.verdict ?? ""), label = typeof f.label === "string" ? f.label : null;
  const reason = typeof f.reason === "string" ? f.reason : null;
  if (state === "queued") return { tone: "wait", label: "Test Flight queued", detail: null };
  if (state === "running") return { tone: "wait", label: "Test Flight running", detail: null };
  if (state === "done" && verdict === "passed") return { tone: "ok", label: label || "Test Flight passed", detail: typeof f.version === "string" ? `Booted on ${f.version}` : null };
  if (state === "done" && verdict === "failed") return { tone: "bad", label: label || "Test Flight failed", detail: reason };
  if (state === "done") return { tone: "warn", label: label || "Test Flight incomplete", detail: reason };
  return { tone: "warn", label: "Test Flight not run", detail: reason };
}

export type BuildRow = { id: string; status: ModBuildView["status"]; label: string; version: string | null; mcVersion: string; createdAt: string; finishedAt: string | null; error: string | null; flight: FlightBadge; head: boolean; installedOn: string | null };
