export function projectCards(builds: ModBuildView[]): ProjectCard[] {
  return groupProjects(builds).map((p) => ({
    rootId: p.rootId, title: p.title, updatedAt: p.updatedAt, builds: p.builds.length,
// Why a build failed, in plain words, from what the row persisted (error, errorCode, result.errorDetail / events).
// The project page shows it after the live follower has unmounted (QA 2026-10-13 remaining item 2). Pure, client-safe.
import type { ModBuildView } from "../builder/types";
import { failInfo } from "../explain";

export type FailureView = { title: string; reason: string; detail: string | null; tips: string[]; retry: boolean };

const clean = (s: string | null | undefined, n: number) => String(s ?? "").replace(/\s+/g, " ").trim().slice(0, n);

export function failureOf(b: Pick<ModBuildView, "status" | "error" | "errorCode" | "result"> | null | undefined): FailureView | null {
  if (!b || b.status !== "failed") return null;
  const info = failInfo(b.errorCode);
  const events = b.result?.events ?? [];
  const lastBad = [...events].reverse().find((e) => /fail|could not|did not|problem|error|blocked|left out/i.test(e.message));
  const reason = clean(b.error, 400) || clean(lastBad?.message, 300) || info.title;
  const raw = clean(b.result?.errorDetail, 500) || clean(lastBad?.detail, 500);
  // never repeat the same words twice; the detail is only worth showing when it adds something
  const detail = raw && raw !== reason && !reason.includes(raw) ? raw : null;
  return { title: info.title, reason, detail, tips: info.tips, retry: info.retry };
}
