export type FlightFailureView = { title: string; reason: string; checks: string[]; refine: true; note: string };

const FLIGHT_LABEL: Record<string, string> = { compile: "compile", scan: "safety scan", boot: "server start", plugins_enabled: "plugin enable", commands_registered: "command registration", datapack_loaded: "data pack load" };

export function flightFailureOf(b: { status?: string; cyrus?: unknown } | null | undefined): FlightFailureView | null {
  if (!b || b.status !== "succeeded") return null;
  const f = (b.cyrus && typeof b.cyrus === "object" ? (b.cyrus as { testFlight?: unknown }).testFlight : null) as { state?: unknown; verdict?: unknown; version?: unknown; checks?: unknown } | null | undefined;
  if (!f || typeof f !== "object" || f.state !== "done" || f.verdict !== "failed") return null;
  const checks = Array.isArray(f.checks) ? (f.checks as { id?: unknown; status?: unknown; detail?: unknown }[]) : [];
  // commands_registered never fails a flight by itself (see gateVerdict); show the hard failures first
