/** Feature or unfeature a PUBLIC, not-taken-down mod page on the marketing surfaces (/mods/cyrus and the cyrus.my landing). */
export async function adminCyrusFeatureListing(fd: FormData) {
  const on = fd.get("on") === "1";
  const admin = await guard("mods.feature");
  const pageId = str(fd, "pageId", 40);
  const page = await cyrusDb.cyrusModPage.findUnique({ where: { id: pageId }, select: { id: true, slug: true, title: true, visibility: true, hiddenAt: true } });
  if (!page) go(fd, "err", "No such mod page.");
  if (on && !(page.visibility === "PUBLIC" && !page.hiddenAt)) go(fd, "err", "Only public mods that are not taken down can be featured.");
  const { FEATURED_KEY, parseFeatured, setFeatured } = await import("./cyrus-mods/featured");
  const before = parseFeatured(await settingValue(FEATURED_KEY));
  const next = setFeatured(before, pageId, on);
  if (!next.ok) go(fd, "err", next.error);
  if (next.list.join() === before.join()) go(fd, "ok", "No change.");
  await setOrClear(FEATURED_KEY, next.list.length ? JSON.stringify(next.list) : null);
  await cyrusAudit({ actorId: admin.id, action: "mods.feature", target: `page:${page.slug}`, before: { featured: before.includes(pageId) }, after: { featured: on, position: on ? next.list.indexOf(pageId) + 1 : null } });
  go(fd, "ok", on ? `“${page.title}” is featured.` : `“${page.title}” is no longer featured.`);
}

