    const strip = (t: string) => t.split("\n").filter((l) => !/^depend:/.test(l)).join("\n");
    assert.equal(strip(r.text), GOB_YML);
    assert.ok(!/^load:/m.test(r.text));
    assert.deepEqual(AF.declaredPlugins(r.text).depend, ["BetterModel"]);
  });
  it("is idempotent and does nothing when already declared", () => {
    const r = AF.fixPluginDepends(GOB_YML, GOB_JAVA, parse)!;
    assert.equal(AF.fixPluginDepends(r.text, GOB_JAVA, parse), null);
  });
  it("inline list, scalar and block list shapes", () => {
    const inline = AF.fixPluginDepends("name: X\nmain: a.B\ndepend: [Vault, Other]  # eco\nversion: '1'\n", BM, parse);
    assert.ok(inline.text.includes("depend: [Vault, Other, BetterModel]"));
    const scalar = AF.fixPluginDepends("name: X\nmain: a.B\ndepend: Vault\n", BM, parse);
    assert.deepEqual(AF.declaredPlugins(scalar.text).depend, ["Vault", "BetterModel"]);
    const block = AF.fixPluginDepends("# header comment\nname: X\nmain: a.B\ndepend:\n  - Vault\n  - Other\ncommands:\n  x:\n    description: y\n", BM, parse);
    assert.ok(block.text.includes("depend:\n  - Vault\n  - Other\n  - BetterModel\ncommands:"));
    assert.ok(block.text.startsWith("# header comment\n"));
    const empty = AF.fixPluginDepends("name: X\nmain: a.B\ndepend:\nversion: 1\n", BM, parse);
    assert.deepEqual(AF.declaredPlugins(empty.text).depend, ["BetterModel"]);
  });
  it("moves BetterModel out of softdepend and drops an emptied softdepend", () => {
    const r = AF.fixPluginDepends("name: X\nmain: a.B\nsoftdepend: [BetterModel]\nversion: 1\n", BM, parse);
    assert.deepEqual(r.changes, [{ kind: "depend-move", plugin: "BetterModel" }]);
    const d = AF.declaredPlugins(r.text);
    assert.deepEqual(d.depend, ["BetterModel"]);
    assert.deepEqual(d.softdepend, []);
    assert.ok(!/softdepend/.test(r.text));
    const keep = AF.fixPluginDepends("name: X\nmain: a.B\nsoftdepend:\n  - Vault\n  - BetterModel\n", BM, parse);
    assert.deepEqual(AF.declaredPlugins(keep.text).softdepend, ["Vault"]);
    assert.deepEqual(AF.declaredPlugins(keep.text).depend, ["BetterModel"]);
  });
  it("creature build without the import still gets BetterModel when forced", () => {
    const r = AF.fixPluginDepends("name: X\nmain: a.B\n", "class A {}", parse, ["BetterModel"]);
    assert.ok(r && r.text.includes("depend: [BetterModel]"));
    assert.equal(AF.fixPluginDepends("name: X\nmain: a.B\n", "class A {}", parse), null);
  });
  it("other managed plugins become softdepend, never depend; declared ones are left alone", () => {
    const java = "import me.clip.placeholderapi.PlaceholderAPI;\nimport net.milkbowl.vault.economy.Economy;\nimport net.luckperms.api.LuckPerms;\nimport com.comphenix.protocol.ProtocolLibrary;\n";
    const r = AF.fixPluginDepends("name: X\nmain: a.B\ndepend: [Vault]\n", java, parse);
    const d = AF.declaredPlugins(r.text);
    assert.deepEqual(d.depend, ["Vault"]);
    assert.deepEqual(d.softdepend, ["PlaceholderAPI", "LuckPerms", "ProtocolLib"]);
    assert.deepEqual(r.changes.map((c: any) => c.kind), ["softdepend-add", "softdepend-add", "softdepend-add"]);
    assert.equal(AF.fixPluginDepends(r.text, java, parse), null);
    // a package that merely starts the same way is not an import of the API
    assert.equal(AF.fixPluginDepends("name: X\nmain: a.B\n", "import me.clipboard.Thing;\n", parse), null);
  });
  it("refuses a result that does not parse (backstop stays the soft check)", () => {
    assert.equal(AF.fixPluginDepends("name: X\nmain: a.B\n", BM, () => { throw new Error("bad"); }), null);
  });
});

describe("rc12 creature check backstop", () => {
  it("flags dependMissing for the goblin plugin.yml and clears after the fix", () => {
    const fs2 = require("node:fs") as typeof fs, os = require("node:os") as typeof import("node:os");
    const ws = fs2.mkdtempSync(path.join(os.tmpdir(), "rc12-"));
    fs2.mkdirSync(path.join(ws, "assets/nx_00000000/creatures"), { recursive: true });
    const java = [{ abs: path.join(ws, "A.java"), rel: "A.java" }];
    fs2.writeFileSync(java[0].abs, `${BM}class A { void f() { BetterModel.model("nx_00000000_goblin"); } }`);
    const bad = CR.checkWorkspaceCreatures(ws, { namespace: "nx_00000000", javaFiles: java, pluginYml: GOB_YML });
    // no spec files in this workspace: the dependency cross-check only runs when creatures exist
    assert.equal(bad.dependMissing, false);
    fs2.writeFileSync(path.join(ws, "assets/nx_00000000/creatures/goblin.json"), "{}");
    const bad2 = CR.checkWorkspaceCreatures(ws, { namespace: "nx_00000000", javaFiles: java, pluginYml: GOB_YML });
    assert.equal(bad2.dependMissing, true);
    assert.ok(bad2.soft.some((s: string) => /depend: \[BetterModel\]/.test(s)));
    const fixed = AF.fixPluginDepends(GOB_YML, BM, parse)!.text;
    const ok = CR.checkWorkspaceCreatures(ws, { namespace: "nx_00000000", javaFiles: java, pluginYml: fixed });
    assert.equal(ok.dependMissing, false);
    fs2.rmSync(ws, { recursive: true, force: true });
  });
});
